def convert_checkout_tables_to_innodb(apps, schema_editor):
    if schema_editor.connection.vendor != 'mysql':
        return
    quote = schema_editor.quote_name
    with schema_editor.connection.cursor() as cursor:
        for table in CHECKOUT_TABLES:
            cursor.execute(
                'SELECT ENGINE FROM information_schema.TABLES '
                'WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=%s',
                [table],
            )
            row = cursor.fetchone()
            if row is None:
                raise RuntimeError(f'required Instagram checkout table is missing: {table}')
            if str(row[0]).lower() != 'innodb':
                schema_editor.execute(f'ALTER TABLE {quote(table)} ENGINE=InnoDB')


